'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var expit = require( '@stdlib/math/base/special/expit' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// MAIN //

/**
* Evaluates the Sigmoid Linear Unit (SiLU) activation function.
*
* @param {number} x - input value
* @returns {number} evaluated SiLU
*
* @example
* var v = silu( 0.0 );
* // returns 0.0
*
* @example
* var v = silu( 1.0 );
* // returns ~0.7311
*
* @example
* var v = silu( -Infinity );
* // returns -0.0
*
* @example
* var v = silu( Infinity );
* // returns Infinity
*
* @example
* var v = silu( NaN );
* // returns NaN
*/
function silu( x ) {
	if ( isnan( x ) ) {
		return NaN;
	}
	if ( x === NINF ) {
		return -0.0;
	}
	return x * expit( x );
}


// EXPORTS //

module.exports = silu;
